    def write_cluster(self, cluster: int, data: bytes) -> None:
        if len(data) < self.cluster_bytes:
            data = data + b"\x00" * (self.cluster_bytes - len(data))
        self.dev.write(self.cluster_offset(cluster), data[:self.cluster_bytes])

